DIR = 'packages/features/feed'


def r(key, tr, en, de, fr, nl, es, pt, it, ru, ar, az, uk, ph=None):
    return (key, ph, tr, en, de, fr, nl, es, pt, it, ru, ar, az, uk)


def pl(key, tr, one_other, ru, ar, uk, ph=None):
    """Plural row: one_other = {lang: (one, other)} for en de fr nl es pt it az; ru/uk/ar given whole."""
    out = [key, ph or {'count': 'int'}, tr]
    for lang in ['en', 'de', 'fr', 'nl', 'es', 'pt', 'it']:
        one, other = one_other[lang]
        out.append('{count, plural, =1{' + one + '} other{' + other + '}}')
    out += [ru, ar, one_other['az'][1], uk]
    return tuple(out)


