SRC_CALLS = {
    "'@${reply.author.username} kullanıcısına yanıt veriyorsun'": 'feedL10n.replyingTo(reply.author.username)',
    "'Yükleniyor: $done/$total'": 'feedL10n.uploading(done, total)',
    "'${g.name} (grup)'": 'feedL10n.groupOption(g.name)',
    "'${i + 1}. medya'": 'feedL10n.mediaN(i + 1)',
    "'▶ ${m.duration?.inSeconds ?? 0} sn'": 'feedL10n.seconds(m.duration?.inSeconds ?? 0)',
    """'"$query" ile başlayan bir etiket bulunamadı.'""": 'feedL10n.noTagMatch(query)',
    "'${formatCount(t.postCount)} gönderi'": 'feedL10n.postCount(t.postCount)',
    "'#$normalized etiketiyle görebileceğin bir gönderi yok.'": 'feedL10n.noTagPosts(normalized)',
    "'Anı · ${event.title}'": 'feedL10n.memoryOf(event.title)',
    "'$emoji tepkisi, ${post.reactions[emoji] ?? 0}'": 'feedL10n.reactionLabel(emoji, post.reactions[emoji] ?? 0)',
    "'Gönderi: ${post.caption}'": 'feedL10n.postWithCaption(post.caption)',
    "'${value.length} kişi gördü'": 'feedL10n.viewedBy(value.length)',
    """'"$title" oluşturuldu.'""": 'feedL10n.highlightCreated(title)',
    "'${h.storyCount} hikaye'": 'feedL10n.storyCount(h.storyCount)',
    """'"${h.title}" öne çıkanına eklendi.'""": 'feedL10n.addedToHighlight(h.title)',
    "'${_selected.length} hikaye seçildi'": 'feedL10n.storiesSelected(_selected.length)',
    "'Hikaye, ${formatDate(s.createdAt)}'": 'feedL10n.storyOn(formatDate(s.createdAt))',
}
